const fetch = require('node-fetch');
const HANDOFF_API = "http://10.215.206.56:5000/human-handoff";

// ================= HANDOFF REQUEST =================
async function triggerHumanHandoff(query) {
    const payload = {
        query: query,
        timestamp: new Date().toISOString(),
        source: 'ai_orchestrator',
        status: 'pending_handoff'
    };

    const response = await fetch(HANDOFF_API, {
        method: 'POST',
        headers: {'Content-Type': 'application/json',
                  'X-Source': 'flowise-orchestrator'
        },
        body: JSON.stringify(payload)
    });

    if (!response.ok) {
        throw new Error(`Handoff API Error: ${response.status} - ${await response.text()}`);
    }

    const data = await response.json();
    return data;
}

